}

// ── references to new records (Reference §6): a `one` field named in `with`, or typed by a shape
// arriving elsewhere in the act, takes `Existing(ref)`, a record on the books, or `New(value)` ──
/** A new Origin: one of NewComposition, NewExternalOrder, NewFermentation. */
sealed interface NewOrigin {
    fun asValue(system: VelleSystem, reg: NewRegistry): Map<String, Any?>
    fun register(reg: NewRegistry)
}
sealed interface OriginReference {
    /** A Origin already on the books. */
    data class Existing(val ref: Ref<Origin>) : OriginReference
    /** A new Origin, created in this commit: nested here when the field is named in `with`, else placed elsewhere in the act. */
    data class New(val value: NewOrigin) : OriginReference
}


// ── the shapes as model objects: what a read returns (Reference §22; OQ51 R5) ──
// A model object is a reference to its own record (`Ref<T>`): equality is identity,
// a reference field is a `Ref<T>` to resolve with `read(ref)`, a membership flag is
// the record's membership at the moment of the read.

data class Peptide(
    override val key: StoreKey,
    val code: String,
    val peptideBatchs: List<Ref<PeptideBatch>>,
) : Ref<Peptide> {
    override val shape: String get() = "Peptide"
    override fun equals(other: Any?) = other is Keyed && other.shape == shape && other.key == key
    override fun hashCode() = 31 * shape.hashCode() + key.hashCode()
}

data class BacteriaStrain(
    override val key: StoreKey,
    val name: String,
    val fermentations: List<Ref<Fermentation>>,
) : Ref<BacteriaStrain> {
    override val shape: String get() = "BacteriaStrain"
    override fun equals(other: Any?) = other is Keyed && other.shape == shape && other.key == key
    override fun hashCode() = 31 * shape.hashCode() + key.hashCode()
}

